// @vitest-environment node
import { afterEach, describe, expect, it, vi } from "vitest";
import { getDemoConfig } from "../src/lib/demo-config";

afterEach(() => {
  vi.unstubAllEnvs();
});

describe("DEMO_REFRESH_SECONDS", () => {
  it.each([
    undefined, "", " ", "\t\n", "0", "-1", "1.5", "NaN", "text",
    "Infinity", "-Infinity", "1e309",
  ])("falls back to 30 for %j", value => {
    vi.stubEnv("DEMO_REFRESH_SECONDS", value);
    expect(getDemoConfig().refreshSeconds).toBe(30);
  });

  it.each([
    ["1", 1], ["30", 30], ["120", 120], [" 42 ", 42], ["\t7\n", 7],
  ])("preserves the positive integer %j", (value, expected) => {
    vi.stubEnv("DEMO_REFRESH_SECONDS", value);
    expect(getDemoConfig().refreshSeconds).toBe(expected);
  });
});

